import re

def validate_ticket_id(raw_value: str) -> str:
    if not re.fullmatch(r"[0-9]{1,10}", raw_value):
        raise ValueError(f"invalid ticket id: {raw_value!r}")
    return raw_value

function sanitizeComment(rawComment, maxLength = 500) {
  if (typeof rawComment !== 'string') {
    throw new Error('comment must be a string');
  }
  const trimmed = rawComment.slice(0, maxLength);
  const noControlChars = trimmed.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');
  const collapsedNewlines = noControlChars.replace(/\n{2,}/g, '\n');
  return collapsedNewlines.trim();
}

function buildPrompt(template, userComment) {
  const safeComment = sanitizeComment(userComment);
  // wrap in clear delimiters so the model treats this as quoted data
  return template.replace(
    '{{comment}}',
    'BEGIN USER COMMENT\n' + safeComment + '\nEND USER COMMENT'
  );
}

